                    system_content += msg["content"] + "\n\n"
                else:
                    if system_content and msg["role"] == "user":
                        msg = dict(msg)
                        msg["content"] = system_content + msg["content"]
                        system_content = ""
                    new_messages.append(msg)
            return new_messages
